mapper.select:
SELECT id, asin, parent_asin AS parentAsin, base_sku AS baseSku, base_msku AS baseMsku, base_store AS baseStore, country, developer, principal, title, listing_tags AS listingTags, product_create_time AS productCreateTime, listing_date AS listingDate, fba_inventory_first_month AS fbaInventoryFirstMonth, inventory_first_store AS inventoryFirstStore, inventory_first_country AS inventoryFirstCountry, inventory_first_sku AS inventoryFirstSku, inventory_first_qty AS inventoryFirstQty, available_first_store AS availableFirstStore, available_first_country AS availableFirstCountry, available_first_sku AS availableFirstSku, available_first_qty AS availableFirstQty, fba_observation_status AS fbaObservationStatus, total_volume AS totalVolume, total_amount AS totalAmount, total_order_items AS totalOrderItems, total_gross_profit AS totalGrossProfit, avg_gross_margin AS avgGrossMargin, active_months AS activeMonths, first_sale_month AS firstSaleMonth, last_sale_month AS lastSaleMonth, latest_month AS latestMonth, latest_volume AS latestVolume, latest_amount AS latestAmount, latest_fba_available AS latestFbaAvailable, latest_cate_rank AS latestCateRank, latest_avg_star AS latestAvgStar, latest_reviews_count AS latestReviewsCount, data_cutoff_month AS dataCutoffMonth, unified_version AS unifiedVersion, synced_at AS syncedAt FROM lingxing_product_unified
AND base_store = #{baseStore}
AND developer = #{developer}
ORDER BY
listing_date
total_volume
total_amount
latest_volume
latest_amount
synced_at
${sortOrder}
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM lingxing_product_unified


        AND base_store = #{baseStore}


        AND developer = #{developer}
